ALTER TABLE public.prescriptions ADD COLUMN IF NOT EXISTS version INTEGER NOT NULL DEFAULT 1; CREATE INDEX IF NOT EXISTS idx_prescriptions_version ON public.prescriptions(version); COMMENT ON COLUMN public.prescriptions.version IS 'Optimistic locking version number. Incremented on each update. Prevents concurrent edit conflicts: UPDATE...WHERE id=X AND version=Y. If version mismatch, client must re-fetch and reconcile.'; CREATE OR REPLACE FUNCTION public.log_prescription_version_conflict() RETURNS TRIGGER AS $fn$ BEGIN INSERT INTO public.audit_logs ( user_id, hospital_id, action_type, entity_type, entity_id, details, severity, created_at ) VALUES ( auth.uid(), NEW.hospital_id, 'prescription_version_conflict', 'prescription', NEW.id, jsonb_build_object('expected_version', OLD.version, 'actual_version', NEW.version, 'timestamp', now()), 'info', now() ); RETURN NEW; END; $fn$ LANGUAGE plpgsql; DROP TRIGGER IF EXISTS prescriptions_update_timestamp ON public.prescriptions; CREATE TRIGGER prescriptions_update_timestamp BEFORE UPDATE ON public.prescriptions FOR EACH ROW EXECUTE FUNCTION public.touch_row_updated_at(); ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS is_active boolean NOT NULL DEFAULT true; COMMENT ON COLUMN public.profiles.is_active IS 'Employment status. When false the user fails user_belongs_to_hospital and loses all hospital-scoped access.'; CREATE OR REPLACE FUNCTION public.user_belongs_to_hospital( _user_id UUID, _hospital_id UUID ) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $fn$ SELECT EXISTS ( SELECT 1 FROM public.profiles WHERE user_id = _user_id AND hospital_id = _hospital_id AND is_active = true ); $fn$; REVOKE ALL ON FUNCTION public.user_belongs_to_hospital(UUID, UUID) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.user_belongs_to_hospital(UUID, UUID) TO authenticated; DROP POLICY IF EXISTS "invoices_hospital_billing_read" ON public.invoices; DROP POLICY IF EXISTS "invoices_select_all" ON public.invoices; CREATE POLICY "invoices_hospital_billing_read" ON public.invoices FOR SELECT USING ( public.user_belongs_to_hospital(auth.uid(), hospital_id) AND EXISTS ( SELECT 1 FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.role IN ('admin', 'receptionist') AND ur.hospital_id = hospital_id ) ); CREATE OR REPLACE FUNCTION public.prevent_audit_log_mutation() RETURNS trigger LANGUAGE plpgsql AS $fn$ BEGIN RAISE EXCEPTION 'audit_logs is append-only: % is not permitted', TG_OP USING ERRCODE = 'insufficient_privilege'; END; $fn$; DROP TRIGGER IF EXISTS trg_audit_logs_immutable ON public.audit_logs; CREATE TRIGGER trg_audit_logs_immutable BEFORE UPDATE OR DELETE ON public.audit_logs FOR EACH ROW EXECUTE FUNCTION public.prevent_audit_log_mutation(); DROP POLICY IF EXISTS "audit_logs_no_update" ON public.audit_logs; CREATE POLICY "audit_logs_no_update" ON public.audit_logs FOR UPDATE TO authenticated USING (false) WITH CHECK (false); DROP POLICY IF EXISTS "audit_logs_no_delete" ON public.audit_logs; CREATE POLICY "audit_logs_no_delete" ON public.audit_logs FOR DELETE TO authenticated USING (false); CREATE TABLE IF NOT EXISTS public.lab_alert_escalations ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), alert_id UUID NOT NULL REFERENCES public.lab_critical_alerts(id) ON DELETE CASCADE, hospital_id UUID NOT NULL REFERENCES public.hospitals(id) ON DELETE CASCADE, escalation_level TEXT NOT NULL CHECK (escalation_level IN ('primary', 'on_call', 'er')), target_user_id UUID REFERENCES public.profiles(id), scheduled_for TIMESTAMPTZ NOT NULL, dispatched_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'dispatched', 'acknowledged', 'cancelled', 'failed')), error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() ); ALTER TABLE public.lab_alert_escalations ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "lab_alert_escalations_hospital_read" ON public.lab_alert_escalations; CREATE POLICY "lab_alert_escalations_hospital_read" ON public.lab_alert_escalations FOR SELECT USING (public.user_belongs_to_hospital(auth.uid(), hospital_id)); CREATE INDEX IF NOT EXISTS idx_lab_alert_escalations_pending ON public.lab_alert_escalations(status, scheduled_for) WHERE status = 'pending'; GRANT SELECT ON public.lab_alert_escalations TO authenticated; GRANT ALL ON public.lab_alert_escalations TO service_role; CREATE OR REPLACE FUNCTION public.cancel_lab_alert_escalations_on_ack() RETURNS trigger LANGUAGE plpgsql AS $fn$ BEGIN IF (NEW.primary_acknowledged_at IS NOT NULL AND OLD.primary_acknowledged_at IS NULL) OR (NEW.is_resolved = true AND OLD.is_resolved = false) THEN UPDATE public.lab_alert_escalations SET status = 'acknowledged', updated_at = now() WHERE alert_id = NEW.id AND status = 'pending'; END IF; RETURN NEW; END; $fn$; DROP TRIGGER IF EXISTS trg_cancel_lab_escalations ON public.lab_critical_alerts; CREATE TRIGGER trg_cancel_lab_escalations AFTER UPDATE ON public.lab_critical_alerts FOR EACH ROW EXECUTE FUNCTION public.cancel_lab_alert_escalations_on_ack(); DROP TRIGGER IF EXISTS trg_activity_logs_immutable ON public.activity_logs; CREATE TRIGGER trg_activity_logs_immutable BEFORE UPDATE OR DELETE ON public.activity_logs FOR EACH ROW EXECUTE FUNCTION public.prevent_audit_log_mutation(); DROP POLICY IF EXISTS "activity_logs_no_update" ON public.activity_logs; CREATE POLICY "activity_logs_no_update" ON public.activity_logs FOR UPDATE TO authenticated USING (false) WITH CHECK (false); DROP POLICY IF EXISTS "activity_logs_no_delete" ON public.activity_logs; CREATE POLICY "activity_logs_no_delete" ON public.activity_logs FOR DELETE TO authenticated USING (false); DROP POLICY IF EXISTS "Staff can insert activity logs" ON public.activity_logs; CREATE POLICY "Staff can insert activity logs" ON public.activity_logs FOR INSERT WITH CHECK ( user_id = auth.uid() AND ( hospital_id IS NULL OR public.user_belongs_to_hospital(auth.uid(), hospital_id) ) ); UPDATE public.user_roles SET role = 'admin' WHERE role::text = 'super_admin'; ALTER TABLE public.user_roles DROP CONSTRAINT IF EXISTS chk_canonical_roles; ALTER TABLE public.user_roles ADD CONSTRAINT chk_canonical_roles CHECK (role::text IN ('admin', 'doctor', 'nurse', 'receptionist', 'pharmacist', 'lab_technician', 'patient'));